{
  "summary": "电场 · 带电粒子偏转",
  "knowledgePoints": [
    {
      "id": "KP1",
      "label": "电场 · 带电粒子偏转",
      "formulas": [
        "E = 1.2",
        "E = state.fieldStrength"
      ],
      "mapsToKg": [
        "S1"
      ]
    }
  ],
  "adjustmentVariables": [
    {
      "id": "AV1",
      "controlId": "s-fieldStrength",
      "label": "场强",
      "type": "range",
      "role": "primary",
      "mapsToKg": "O1",
      "monotonicity": "monotone",
      "affects": [
        "deflection"
      ],
      "notes": "rank1：场强直接改偏转，线性主控",
      "priorityRank": 1,
      "responseShape": "linear-approx"
    },
    {
      "id": "AV2",
      "controlId": "s-charge",
      "label": "电荷量",
      "type": "range",
      "role": "secondary",
      "mapsToKg": "O1",
      "monotonicity": "monotone",
      "affects": [
        "deflection"
      ],
      "notes": "rank2：电荷量改受力，线性次控",
      "priorityRank": 2,
      "responseShape": "linear-approx"
    }
  ],
  "confoundingVariables": [
    {
      "id": "CV1",
      "controlId": "s-plate-gap",
      "label": "极板间距",
      "reason": "仅改变极板示意间距，E 独立设定，不参与偏转归因"
    }
  ],
  "inquiryFlow": [
    "KP1",
    "AV1",
    "AV2",
    "CV1"
  ],
  "narrative": {
    "intro": "本关探究：偏转原理、控制变量法、电场力公式",
    "steps": [
      {
        "order": 1,
        "title": "明确知识点",
        "body": "回顾：偏转原理；控制变量法；电场力公式",
        "mapsToKg": [
          "S1",
          "S2",
          "S3"
        ]
      },
      {
        "order": 2,
        "title": "识别调节变量",
        "body": "可调节：场强、电荷量；极板间距仅为示意无效控件。建议控制变量法，每次只改一项有效变量。",
        "mapsToKg": [
          "O1",
          "O1"
        ]
      },
      {
        "order": 3,
        "title": "识别混淆变量",
        "body": "混淆项：极板间距（示意无效，不改变偏转）",
        "mapsToKg": [
          "I1"
        ]
      },
      {
        "order": 4,
        "title": "观察—调整—再测",
        "body": "操作后观察结果，未达标则微调调节变量并重复，直至满足约束过关。",
        "mapsToKg": [
          "O1"
        ]
      }
    ]
  },
  "outputVariables": [
    {
      "id": "OV1",
      "label": "过关结果",
      "symbol": "",
      "unit": "",
      "role": "primary",
      "source": "observe"
    }
  ],
  "domain": "efield"
}

