{
  "summary": "钟表铺·校时",
  "knowledgePoints": [
    {
      "id": "KP1",
      "label": "钟表铺·校时",
      "formulas": [
        "T ≈ 2π√(L/g)"
      ],
      "mapsToKg": [
        "S1"
      ]
    }
  ],
  "adjustmentVariables": [
    {
      "id": "AV1",
      "controlId": "s-len",
      "label": "摆长",
      "type": "range",
      "role": "primary",
      "mapsToKg": "O1",
      "monotonicity": "monotone",
      "affects": [],
      "notes": "rank1：摆长主控，T∝√L 非线性单调，校时首选",
      "priorityRank": 1,
      "responseShape": "nonlinear-monotone"
    },
    {
      "id": "AV2",
      "controlId": "s-angle",
      "label": "摆角",
      "type": "range",
      "role": "secondary",
      "mapsToKg": "O1",
      "monotonicity": "monotone",
      "affects": [
        "R",
        "H"
      ],
      "notes": "rank2：摆角仅弱 θ² 修正周期，并需满足最小摆幅",
      "priorityRank": 2,
      "responseShape": "nonlinear-monotone"
    }
  ],
  "confoundingVariables": [
    {
      "id": "CV1",
      "controlId": "s-mass",
      "label": "质量",
      "reason": "混淆/装饰控件：不参与核心过关归因"
    }
  ],
  "inquiryFlow": [
    "KP1",
    "AV1",
    "OV1"
  ],
  "narrative": {
    "intro": "巷子深处的钟表铺打了烊，只剩你和这座祖父钟。它一天要慢上三个多小时，老师傅临走前只留下一句：毛病出在摆上。摆的周期对了，钟就准了。",
    "steps": [
      {
        "order": 1,
        "title": "自由探究",
        "body": "先自由调摆，摸清周期与摆长；再切竞赛接急单目标带（本局锁定，校偏不换题）。",
        "mapsToKg": [
          "P1",
          "C1",
          "C2",
          "O1"
        ]
      },
      {
        "order": 2,
        "title": "启动计时",
        "body": "点击启动计时按钮，等待一个周期后获得实测周期值。",
        "mapsToKg": [
          "C4"
        ]
      },
      {
        "order": 3,
        "title": "观察与调整",
        "body": "观察实测周期是否在目标带内，若偏快或偏慢则调整摆长，若摆幅不足则增大摆角。",
        "mapsToKg": [
          "C5",
          "C6",
          "O1"
        ]
      },
      {
        "order": 4,
        "title": "过关",
        "body": "周期在目标带且摆幅≥15°，钟声归位，校准完成。",
        "mapsToKg": [
          "R1"
        ]
      }
    ]
  },
  "outputVariables": [
    {
      "id": "OV1",
      "label": "射程",
      "symbol": "R",
      "unit": "m",
      "role": "primary",
      "source": "formula"
    },
    {
      "id": "OV2",
      "label": "最大高度",
      "symbol": "H",
      "unit": "m",
      "role": "secondary",
      "source": "formula"
    }
  ],
  "domain": "projectile"
}

